<?php use App\Core\Security;?><h4 class="mb-3">تأمین‌کنندگان</h4><form method="post" class="card card-body mb-3"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="row g-2"><div class="col-md-2"><input name="code" class="form-control" placeholder="کد"></div><div class="col-md-3"><input name="name" class="form-control" placeholder="نام" required></div><div class="col-md-2"><input name="phone" class="form-control" placeholder="تلفن"></div><div class="col-md-3"><input name="email" class="form-control" placeholder="ایمیل"></div><div class="col-md-2"><button class="btn btn-primary w-100">ثبت</button></div></div><input name="contact_name" class="form-control mt-2" placeholder="نام تماس"><textarea name="notes" class="form-control mt-2" placeholder="توضیحات"></textarea></form><div class="table-responsive"><table class="table table-bordered align-middle"><thead><tr><th>کد</th><th>نام</th><th>تلفن</th><th>ایمیل</th><th>تماس</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($suppliers as $r):?><tr><form method="post" action="/pricing/public/admin/suppliers/<?=(int)$r['id']?>"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><td><input name="code" value="<?=Security::e($r['code'])?>" class="form-control form-control-sm"></td><td><input name="name" value="<?=Security::e($r['name'])?>" class="form-control form-control-sm" required></td><td><input name="phone" value="<?=Security::e($r['phone'])?>" class="form-control form-control-sm"></td><td><input name="email" value="<?=Security::e($r['email'])?>" class="form-control form-control-sm"></td><td><input name="contact_name" value="<?=Security::e($r['contact_name'])?>" class="form-control form-control-sm"></td><td><?=$r['is_active']?'فعال':'غیرفعال'?></td><td><input name="notes" value="<?=Security::e($r['notes'])?>" class="form-control form-control-sm mb-1"><button class="btn btn-sm btn-outline-primary">ذخیره</button></form><form method="post" action="/pricing/public/admin/suppliers/<?=(int)$r['id']?>/archive" class="d-inline"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><button class="btn btn-sm btn-outline-danger"><?=$r['is_active']?'غیرفعال':'فعال'?></button></form></td></tr><?php endforeach;?></tbody></table></div>